import * as T from './vendor/three.module.js';
import {DESTINATION_STATIONS,atDestination,bookHotel,cancelHotel,restHotel,buyTakeaway,startDance,danceTick,danceBeat,collectBeach,depositBeach} from './destinations-state.js';
import {heldMeal} from './home-life.js';
import {animateActivity} from './activity-pose.js';
import {makeCharacter,animateCharacter} from './character.js';
import {aimHand,handPoint} from './home-motion.js';
export function createDestinationPlay({state,scene,player,location,rooms,commit,save,toast,stopInput}){
 const $=id=>document.getElementById(id),ui=$('destination-ui');let action=null,panel=null,clock=0,lastSave=0,caretaker=null;
 const bag=new T.Mesh(new T.BoxGeometry(.25,.35,.2),new T.MeshStandardMaterial({color:'#638c72',roughness:.9}));scene.add(bag);bag.visible=false;
 function result(r){commit(r);return r?.ok;}
 function hide(){panel=null;ui.innerHTML='';ui.classList.add('hidden');}
 function show(html){ui.classList.remove('hidden');ui.innerHTML='<button id="destination-close" aria-label="Close activity">×</button>'+html;$('destination-close').onclick=()=>{stop();hide();};}
 function stop(){if(action){const a=action;action=null;player().position.set(a.stand.x,.16,a.stand.z);player().rotation.set(0,0,0);animateCharacter(player(),0,false);save();}hide();}
 function begin(kind,station,duration,complete){if(heldMeal(state)&&kind!=='pick'){toast('Store the carried meal before starting this activity.');return;}if(action||!atDestination(location(),player().position,location(),station))return;stopInput();const stand=DESTINATION_STATIONS[location()][station];action={kind,station,stand:{...stand},view:location(),elapsed:0,duration,complete};show('<strong id="destination-status"></strong><progress id="destination-progress" max="100" value="0"></progress>'+(kind==='dance'?'<button id="destination-beat">Tap on green</button>':'')+'<button id="destination-cancel">Cancel / pause</button>');$('destination-cancel').onclick=stop;if(kind==='dance')$('destination-beat').onclick=()=>{const d=state.cityVisits.club;result(danceBeat(state,d.id,Math.floor(d.elapsed),location(),player().position));};}
 function station(id){const view=location(),p=player().position;if(!atDestination(view,p,view,id))return toast('Approach this activity first.');if(action)return;panel={view,id};if(view==='island-house'&&id==='desk'){const h=state.cityVisits.hotel,serial=state.cityVisits.hotelSerial;show('<strong>Tide Courtyard reception</strong><p>Private rest room · ₦700 per two-game-hour rest · +45 energy. Refund before use.</p><button id="hotel-book">Book rest room · ₦700</button>'+(h?.status==='booked'?'<button id="hotel-refund">Cancel unused booking</button>':''));$('hotel-book').disabled=h?.status==='booked';$('hotel-book').onclick=()=>{if(result(bookHotel(state,serial,location(),player().position)))hide();};if($('hotel-refund'))$('hotel-refund').onclick=()=>{if(result(cancelHotel(state,h.id,location(),player().position)))hide();};}
 else if(view==='island-house'){const h=state.cityVisits.hotel;if(h?.status!=='booked')return toast('Book a rest room at reception first.');begin('rest','bed',8,()=>restHotel(state,h.id,location(),player().position));}
 else if(view==='islandfood'){const serial=state.cityVisits.mealSerial;show('<strong>Lagoon Pot · pepper yam</strong><p>₦700 per takeaway. Collect a physical meal; eat or store it at home.</p><button id="lagoon-buy">Confirm takeaway · ₦700</button>');$('lagoon-buy').onclick=()=>{if(result(buyTakeaway(state,serial,location(),player().position)))hide();};}
 else if(view==='club'){if(result(startDance(state,state.cityVisits.clubSerial,view,p)))begin('dance','dance',Infinity,null);}
 else if(view==='beach'&&id==='bin')result(depositBeach(state,view,p));else if(view==='beach'){const index=Number(id.slice(-1));begin('pick',id,1,()=>collectBeach(state,index,location(),player().position));}}
 return {busy:()=>!!action,safePosition:()=>action?.stand,stop,station,get action(){return action;},get caretaker(){return caretaker;},context(){const view=location(),stations=DESTINATION_STATIONS[view];if(!stations||action)return null;const b=state.cityVisits.beach,ids=Object.entries(stations).filter(([id])=>!id.startsWith('litter')||!b.deposited&&!b.collected.includes(Number(id.slice(-1)))||b.deposited&&b.day!==state.day);const closest=ids.map(([id,p])=>({id,d:Math.hypot(player().position.x-p.x,player().position.z-p.z)})).sort((a,b)=>a.d-b.d)[0];if(closest?.d<1.05)return {id:'destination-'+closest.id,label:({desk:'Hotel reception',bed:'Rest in booked room',dance:'Dance · four green beats',counter:'Collect pepper yam · ₦700',bin:'Recycle collected litter'})[closest.id]||'Pick up litter',run:()=>station(closest.id)};if(caretaker?.visible&&view==='beach'&&Math.hypot(player().position.x-caretaker.position.x+rooms().beach.room.position.x,player().position.z-caretaker.position.z)<1.6)return {id:'beach-caretaker',label:'Talk · Efe (NPC)',run:()=>toast('Efe: Please collect the three pieces of litter and use the green bin. Thank you!')};return null;},tick(dt){clock+=dt;const view=location(),room=rooms()[view],p=player();if(panel&&(!atDestination(view,p.position,panel.view,panel.id)||view!==panel.view)&&!action)hide();if(action){const a=action;a.elapsed+=dt;const origin=room.room.position.x;if(a.kind==='rest'){p.position.set(-2.9,1.15,-.5);p.rotation.set(-Math.PI/2,0,0);animateActivity(p,'sleep',dt,a.elapsed);}else if(a.kind==='pick'){animateActivity(p,'cook',dt,a.elapsed);aimHand(p,'l',new T.Vector3(origin+a.stand.x,.35,a.stand.z-.15));}else {danceTick(state,dt);const d=state.cityVisits.club;p.position.set(Math.sin(d.elapsed*5)*.08,.16+Math.abs(Math.sin(d.elapsed*5))*.025,-.6);p.rotation.y=Math.sin(d.elapsed*3)*.18;animateActivity(p,'wash',dt,d.elapsed);for(const side of ['l','r'])aimHand(p,side,new T.Vector3(origin+p.position.x+(side==='l'?.45:-.45),1.3+Math.sin(d.elapsed*5+(side==='l'?0:2))*.28,-.3));const green=d.elapsed%1>=.25&&d.elapsed%1<=.7;$('destination-beat').textContent=green?'GREEN · tap':'Wait for green';$('destination-beat').classList.toggle('beat-ready',green);room.refs.beat.material.color.set(green?'#719f75':'#bbaa68');if(d.finished||d.elapsed>=180){if(!d.finished){d.finished=true;toast('Session timed out. Start another free session.');}stop();}}
 if(action){$('destination-status').textContent=a.kind==='dance'?'Dance · '+state.cityVisits.club.hits+'/4 beats':a.kind==='rest'?'Resting · '+Math.ceil(a.duration-a.elapsed)+'s':'Picking up litter';$('destination-progress').value=a.kind==='dance'?state.cityVisits.club.hits*25:Math.min(100,a.elapsed/a.duration*100);if(a.elapsed>=a.duration){const complete=a.complete;stop();if(complete)result(complete());}if(clock-lastSave>1){save();lastSave=clock;}}}
 const b=state.cityVisits.beach;if(view==='beach'){room.refs.litter.forEach((m,i)=>m.visible=b.deposited?b.day!==state.day:!b.collected.includes(i));if(!caretaker){caretaker=makeCharacter({sex:'female',skin:'#885037',hair:'locs',shirt:'#b28c53',outfit:'streetwear',accessory:'none'});caretaker.userData.publicName='Efe · NPC · caretaker';caretaker.traverse(o=>{if(o.isMesh)o.castShadow=false;});scene.add(caretaker);}caretaker.visible=true;const x=Math.sin(clock*.18)*3;caretaker.position.set(room.room.position.x+x,.16,-3.3);caretaker.rotation.y=Math.cos(clock*.18)>0?Math.PI/2:-Math.PI/2;animateCharacter(caretaker,dt,true);}else if(caretaker)caretaker.visible=false;
 bag.visible=view==='beach'&&!b.deposited&&b.collected.length>0&&!action;if(bag.visible){aimHand(p,'l',p.getWorldPosition(new T.Vector3()).add(new T.Vector3(.4,1.1,.2)));bag.position.copy(handPoint(p,'l')).add(new T.Vector3(0,-.18,0));}
 }};
}
